var response = await client.PriceDisplaySettings.GetPriceDisplaySettingsAsync();
var body = (IReadOnlyDictionary<string, object?>)response.Map!;
var priceDisplaySettings = (IReadOnlyDictionary<string, object?>)body["price_display_settings"]!;
var orderItem = (IReadOnlyDictionary<string, object?>)priceDisplaySettings["order_item"]!;
var priceIncludingTax = (IReadOnlyDictionary<string, object?>)orderItem["price_including_tax"]!;
Console.WriteLine($"{priceIncludingTax["enabled"]} {priceIncludingTax["customize"]}");

